<template><div class="list-page"><el-card shadow="never" class="!border-none"><el-form inline :model="filters"><el-form-item label="业务员名称"><el-input v-model="filters.name" clearable placeholder="请输入业务员名称" /></el-form-item><el-form-item label="所属经销商"><el-select v-model="filters.dealer" filterable clearable><el-option v-for="item in dealers" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="手机号码"><el-input v-model="filters.phone" clearable /></el-form-item><el-form-item label="创建时间"><el-date-picker v-model="filters.dateRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" /></el-form-item><el-form-item><el-button type="primary" @click="page=1">查询</el-button><el-button @click="reset">重置</el-button><el-button @click="exportData">导出</el-button></el-form-item></el-form></el-card><el-card shadow="never" class="!border-none mt-4"><template #header><div class="heading"><span>业务员列表</span></div></template><el-table :data="paged" stripe table-layout="fixed"><el-table-column prop="name" label="业务员姓名" min-width="150" /><el-table-column prop="phone" label="手机号码" min-width="150" /><el-table-column prop="dealer" label="所属经销商" min-width="220" /><el-table-column prop="enabled" label="状态" min-width="90"><template #default="{row}"><el-switch v-model="row.enabled" /></template></el-table-column><el-table-column prop="createdAt" label="创建时间" min-width="170" /><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="success" @click="recharge(row)">充值</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" background layout="total,prev,pager,next" :total="filtered.length" /></div></el-card><el-dialog v-model="rechargeVisible" title="业务员积分充值" width="480px"><el-form :model="rechargeForm" label-width="90px"><el-form-item label="业务员"><el-input v-model="rechargeForm.name" disabled /></el-form-item><el-form-item label="充值类型"><el-radio-group v-model="rechargeForm.type"><el-radio value="增加">增加</el-radio><el-radio value="扣减">扣减</el-radio></el-radio-group></el-form-item><el-form-item label="充值数值"><el-input-number v-model="rechargeForm.amount" :min="1" /></el-form-item></el-form><template #footer><el-button @click="rechargeVisible=false">取消</el-button><el-button type="primary" @click="confirmRecharge">确认</el-button></template></el-dialog></div></template>
<script setup lang="ts" name="businessLists">
const dealers=['华东食品商贸有限公司','华南优选供应链有限公司','华北盛达商贸有限公司']; const names=['张明','李婷','王强','赵颖']; const rows=reactive<any[]>(Array.from({length:18},(_,i)=>({id:`YW${10001+i}`,name:names[i%4],phone:`138${String(10000000+i*137).slice(0,8)}`,dealer:dealers[i%3],enabled:i%5!==0,createdAt:`2026-09-${String(3-i%3).padStart(2,'0')} 10:20:00`}))); const filters=reactive({name:'',dealer:'',phone:'',dateRange:[] as string[]}); const page=ref(1); const filtered=computed(()=>rows.filter(r=>(!filters.name||r.name.includes(filters.name))&&(!filters.dealer||r.dealer===filters.dealer)&&(!filters.phone||r.phone.includes(filters.phone))&&(filters.dateRange.length!==2||r.createdAt.slice(0,10)>=filters.dateRange[0]&&r.createdAt.slice(0,10)<=filters.dateRange[1]))); const paged=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10)); const reset=()=>{Object.assign(filters,{name:'',dealer:'',phone:'',dateRange:[]});page.value=1}; const rechargeVisible=ref(false); const rechargeForm=reactive({name:'',type:'增加',amount:100}); const recharge=(r:any)=>{rechargeForm.name=r.name;rechargeVisible.value=true}; const confirmRecharge=()=>{rechargeVisible.value=false;ElMessage.success('充值记录已保存')}; const remove=async(r:any)=>{try{await ElMessageBox.confirm(`确认删除业务员“${r.name}”吗？`,'删除确认',{type:'warning'});rows.splice(rows.indexOf(r),1)}catch{}}; const exportData=()=>{const data=[['ID','业务员姓名','手机号码','所属经销商','状态','创建时间'],...filtered.value.map(r=>[r.id,r.name,r.phone,r.dealer,r.enabled?'启用':'禁用',r.createdAt])];const url=URL.createObjectURL(new Blob([data.map(r=>r.join(',')).join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='业务员列表.csv';a.click();URL.revokeObjectURL(url)}
</script><style scoped>.list-page :deep(.el-input),.list-page :deep(.el-select){width:200px}.heading{display:flex;justify-content:space-between}.pagination{display:flex;justify-content:flex-end;margin-top:16px}</style>
